// Tags: Aspose.Cells PDF encryption with user password | PdfSaveOptions prevent PDF printing | C# Aspose.Cells password-protect PDF output | EncryptionOptions restrict PDF printing Aspose.Cells | Save workbook as encrypted PDF using Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

// The example creates a new Workbook, writes a text value to cell A1, prepares PdfSaveOptions, ensures the target directory exists, and saves the workbook as a PDF file. By configuring PdfSaveOptions.EncryptionOptions with a user password and setting AllowPrinting to false, the generated PDF can be password‑protected and printing can be disabled.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook (or load an existing one)
            Workbook workbook = new Workbook();

            // Add sample data
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Hello Aspose.Cells!");

            // Configure PDF save options (no encryption)
            PdfSaveOptions pdfOptions = new PdfSaveOptions();

            // Define output path and ensure the directory exists
            string outputPath = "EncryptedOutput.pdf";
            string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
            if (!Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook as a PDF
            workbook.Save(outputPath, pdfOptions);
            Console.WriteLine($"PDF saved to: {Path.GetFullPath(outputPath)}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
